var i=6;var t=[{id:`cooking-006-01`,theoryId:6,type:`calculation`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Convert 0.75 kg of rice to grams.`,ua:`Переведіть 0,75 кг рису в грами.`},explanation:{en:`One kilogram equals 1,000 grams, so 0.75 × 1,000 = 750 g.`,ua:`Один кілограм дорівнює 1000 грамам, отже 0,75 × 1000 = 750 г.`},numericInput:{unit:`g`,allowDecimals:!1,unitLabel:{en:`grams`,ua:`грамів`}},answer:{value:750,tolerance:0,unit:`g`}},{id:`cooking-006-02`,theoryId:6,type:`calculation`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`How many milliliters are in 2.5 liters of stock?`,ua:`Скільки мілілітрів у 2,5 літра бульйону?`},explanation:{en:`Multiply liters by 1,000.`,ua:`Помножте літри на 1000.`},numericInput:{unit:`mL`,allowDecimals:!1,unitLabel:{en:`milliliters`,ua:`мілілітрів`}},answer:{value:2500,tolerance:0,unit:`mL`}},{id:`cooking-006-03`,theoryId:6,type:`calculation`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A recipe uses 3 tablespoons, each defined as 15 mL. How many milliliters is that?`,ua:`У рецепті 3 столові ложки по 15 мл. Скільки це мілілітрів?`},explanation:{en:`3 × 15 mL = 45 mL. Tablespoon standards can vary by region.`,ua:`3 × 15 мл = 45 мл. Стандарт об’єму столової ложки залежить від країни.`},numericInput:{unit:`mL`,allowDecimals:!1,unitLabel:{en:`milliliters`,ua:`мілілітрів`}},answer:{value:45,tolerance:0,unit:`mL`}},{id:`cooking-006-04`,theoryId:6,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Why is a kitchen scale usually more reproducible for flour?`,ua:`Чому кухонні ваги зазвичай забезпечують точніше повторення кількості борошна?`},explanation:{en:`Packing changes mass per cup; mass measurements avoid this variation.`,ua:`Утрамбовування змінює масу склянки; зважування прибирає цю похибку.`},options:[{id:`a`,text:{en:`Packed and loose flour have different cup volumes`,ua:`Утрамбоване та пухке борошно мають різну масу в одному об’ємі`}},{id:`b`,text:{en:`Scales change the chemical composition`,ua:`Ваги змінюють хімічний склад`}},{id:`c`,text:{en:`Volume measures never work for liquids`,ua:`Об’ємні мірки непридатні для рідин`}},{id:`d`,text:{en:`A scale automatically removes lumps`,ua:`Ваги автоматично видаляють грудочки`}}],answer:{optionIds:[`a`]}},{id:`cooking-006-05`,theoryId:6,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`One cup of flour and one cup of water always weigh the same.`,ua:`Одна склянка борошна й одна склянка води завжди мають однакову масу.`},explanation:{en:`Mass depends on density; equal volumes need not have equal mass.`,ua:`Маса залежить від густини, тому однакові об’єми можуть важити по-різному.`},answer:{value:!1}},{id:`cooking-006-06`,theoryId:6,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match each measurement to the correct equivalent.`,ua:`Поєднайте одиницю вимірювання з правильним еквівалентом.`},explanation:{en:`Metric prefixes make ingredient scaling predictable.`,ua:`Метричні префікси допомагають точно масштабувати інгредієнти.`},leftItems:[{id:`l1`,text:{en:`1 kilogram`,ua:`1 кілограм`}},{id:`l2`,text:{en:`1 liter`,ua:`1 літр`}},{id:`l3`,text:{en:`0.5 kilogram`,ua:`0,5 кілограма`}}],rightItems:[{id:`r3`,text:{en:`500 grams`,ua:`500 грамів`}},{id:`r2`,text:{en:`1,000 milliliters`,ua:`1000 мілілітрів`}},{id:`r1`,text:{en:`1,000 grams`,ua:`1000 грамів`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}}];var n={theoryId:6,exercises:t};export{n as default,t as exercises,i as theoryId};